(41, 1, '2026-10-08 18:34:44', '2026-10-08 15:34:44', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"swp-florist\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"metadata\":{\"name\":\"Тема дня\",\"patternName\":\"swp-florist/hero\",\"description\":\"Панель «Frosted Hero» с заголовком, двумя призывами к действию, статистикой доставки и фотографией букета в форме арки с парящими чипсами.\",\"categories\":[\"banner\",\"featured\",\"swp-florist\"]},\"align\":\"full\",\"className\":\"swp-panel swp-hero\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|gutter\",\"right\":\"var:preset|spacing|gutter\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"backgroundColor\":\"cream\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"anchor\":\"onas\"} -->\n<div class=\"wp-block-group alignfull swp-panel swp-hero has-cream-background-color has-background\" id=\"onas\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-right:var(--wp--preset--spacing--gutter);padding-bottom:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--gutter)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"56px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"52.5%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:52.5%\"><!-- wp:paragraph {\"className\":\"swp-eyebrow\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"20px\"}}}} -->\n<p class=\"swp-eyebrow\" style=\"margin-top:0;margin-bottom:20px\">Доставка по всему городу в течение 2 часов</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"22px\"}}},\"fontSize\":\"h1\"} -->\n<h1 class=\"wp-block-heading has-h-1-font-size\" style=\"margin-top:0;margin-bottom:22px\">Начни свой день с чая</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"swp-lead\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"34px\"}}}} -->\n<p class=\"swp-lead\" style=\"margin-top:0;margin-bottom:34px\"><strong>Tea Garden</strong> — это пространство эстетики и домашнего уюта. Мы создаем ароматные авторские миксы из отборного чая, спелых ягод и целебных трав, которые согревают и дарят настроение. А чтобы каждый глоток приносил эстетическое удовольствие, мы подобрали коллекцию изящных чайников и стильных чайных пар. Соберите свой идеальный ритуал или готовый подарок для близких.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"16px\",\"margin\":{\"top\":\"0\",\"bottom\":\"46px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:0;margin-bottom:46px\"><!-- wp:button {\"className\":\"swp-btn-arrow\"} -->\n<div class=\"wp-block-button swp-btn-arrow\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://mysitekkr.rus/shop/\">Просмотреть ассортимент</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:group {\"className\":\"swp-hero-stats\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group swp-hero-stats\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"swp-stat-n\"} -->\n<p class=\"swp-stat-n\">2<em> ч</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"swp-stat-t\"} -->\n<p class=\"swp-stat-t\">Стандартная доставка по городу</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"swp-stat-n\"} -->\n<p class=\"swp-stat-n\">100<em>%</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"swp-stat-t\"} -->\n<p class=\"swp-stat-t\">Натуральный цельнолистовой чай</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"swp-stat-n\"} -->\n<p class=\"swp-stat-n\">7<em> дней</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"swp-stat-t\"} -->\n<p class=\"swp-stat-t\">Гарантия возврата, если вкус не понравился </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"47.5%\",\"className\":\"swp-hero-visual\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center swp-hero-visual\" style=\"flex-basis:47.5%\"><!-- wp:group {\"className\":\"swp-arch-wrap\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swp-arch-wrap\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"id\":55,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"swp-arch\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image size-full swp-arch\" style=\"margin-top:0;margin-bottom:0\"><img src=\"http://mysitekkr.rus/wp-content/uploads/2026/10/1000091590-2.jpg\" alt=\"\" class=\"wp-image-55\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Фирменные букеты\",\"patternName\":\"swp-florist/bouquets\",\"description\":\"Фирменная сетка «Букет». При активном плагине показывает реальные товары WooCommerce в реальном времени, в противном случае - сетку карточек, созданных вручную.\",\"categories\":[\"featured\",\"products\",\"swp-florist\",\"swp-florist-shop\"]},\"align\":\"full\",\"className\":\"swp-panel swp-bouquets\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|gutter\",\"right\":\"var:preset|spacing|gutter\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"anchor\":\"tea\"} -->\n<div class=\"wp-block-group alignfull swp-panel swp-bouquets\" id=\"tea\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-right:var(--wp--preset--spacing--gutter);padding-bottom:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--gutter)\"><!-- wp:group {\"className\":\"swp-section-head\",\"style\":{\"spacing\":{\"blockGap\":\"32px\",\"margin\":{\"top\":\"0\",\"bottom\":\"52px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group swp-section-head\" style=\"margin-top:0;margin-bottom:52px\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"640px\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"swp-eyebrow\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"16px\"}}}} -->\n<p class=\"swp-eyebrow\" style=\"margin-top:0;margin-bottom:16px\">Фирменные вкусы</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"18px\"}}},\"fontSize\":\"h2\"} -->\n<h2 class=\"wp-block-heading has-h-2-font-size\" style=\"margin-top:0;margin-bottom:18px\"><strong>Наполненный спелыми ягодами </strong>и теплом</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"swp-lead\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<p class=\"swp-lead\" style=\"margin-top:0;margin-bottom:0\">Наши фирменные чайные миксы мы создаем небольшими партиями и упаковываем вручную непосредственно перед отправкой. Это позволяет сохранить всю сочность натуральных ягод, аромат алтайских трав и цельных чайных листьев. Добавьте к этому эстетичную посуду из нашей коллекции, чтобы превратить обычное чаепитие в настоящий праздник.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://mysitekkr.rus/shop/\">Смотреть весь каталог</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:woocommerce/product-collection {\"queryId\":10,\"query\":{\"perPage\":6,\"pages\":1,\"offset\":0,\"postType\":\"product\",\"order\":\"desc\",\"orderBy\":\"date\",\"search\":\"\",\"exclude\":[],\"inherit\":false,\"taxQuery\":[],\"isProductCollectionBlock\":true,\"featured\":false,\"woocommerceOnSale\":false,\"woocommerceStockStatus\":[\"instock\",\"outofstock\",\"onbackorder\"],\"woocommerceAttributes\":[],\"woocommerceHandPickedProducts\":[],\"filterable\":false},\"tagName\":\"div\",\"displayLayout\":{\"type\":\"flex\",\"columns\":3,\"shrinkColumns\":true},\"dimensions\":{\"widthType\":\"fill\"},\"queryContextIncludes\":[\"collection\"]} -->\n<div class=\"wp-block-woocommerce-product-collection\"><!-- wp:woocommerce/product-template -->\n<!-- wp:woocommerce/product-image {\"showSaleBadge\":false,\"imageSizing\":\"thumbnail\",\"isDescendentOfQueryLoop\":true,\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"20px\"}}}} -->\n<!-- wp:woocommerce/product-sale-badge {\"align\":\"right\"} /-->\n<!-- /wp:woocommerce/product-image -->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"4px\"}}},\"__woocommerceNamespace\":\"woocommerce/product-collection/product-title\"} /-->\n\n<!-- wp:woocommerce/product-summary {\"isDescendentOfQueryLoop\":true,\"showDescriptionIfEmpty\":true,\"summaryLength\":70,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"14px\"}},\"typography\":{\"fontSize\":\"13.2px\"}}} /-->\n\n<!-- wp:group {\"className\":\"swp-bq-foot\",\"style\":{\"spacing\":{\"blockGap\":\"12px\",\"margin\":{\"top\":\"0\"}}}} -->\n<div class=\"wp-block-group swp-bq-foot\" style=\"margin-top:0\"><!-- wp:woocommerce/product-price {\"isDescendentOfQueryLoop\":true} /-->\n\n<!-- wp:woocommerce/product-button {\"isDescendentOfQueryLoop\":true} /--></div>\n<!-- /wp:group -->\n<!-- /wp:woocommerce/product-template -->\n\n<!-- wp:woocommerce/product-collection-no-results -->\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">В магазин пока не добавлено ни одного букета.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:woocommerce/product-collection-no-results --></div>\n<!-- /wp:woocommerce/product-collection --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Подписка на цветы\",\"patternName\":\"swp-florist/subscription\",\"description\":\"Панель «Глубокая орхидея» с текстом подписки и тремя взаимосвязанными планами доставки.\",\"categories\":[\"call-to-action\",\"swp-florist\"]},\"align\":\"full\",\"className\":\"swp-sub-panel\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|gutter\",\"right\":\"var:preset|spacing|gutter\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|plum\"},\":hover\":{\"color\":{\"text\":\"var:preset|color|plum\"}}}}},\"textColor\":\"plum\",\"gradient\":\"subscription\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"anchor\":\"swp-subscription\"} -->\n<div class=\"wp-block-group alignfull swp-sub-panel has-plum-color has-subscription-gradient-background has-text-color has-background has-link-color\" id=\"swp-subscription\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-right:var(--wp--preset--spacing--gutter);padding-bottom:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--gutter)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"44px\",\"left\":\"52px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"55%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:55%\"><!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"18px\"}},\"color\":{\"text\":\"#ffffff\"}},\"fontSize\":\"h2\"} -->\n<h2 class=\"wp-block-heading has-text-color has-h-2-font-size\" style=\"color:#ffffff;margin-top:0;margin-bottom:18px\">Чайный блог и новости клуба</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"swp-lead\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"text\":\"rgba(255,255,255,0.85)\"}}} -->\n<p class=\"swp-lead has-text-color\" style=\"color:rgba(255,255,255,0.85);margin-top:0;margin-bottom:0\">Откройте для себя мир чайной эстетики и уюта. Рассказываем, как создаются наши фирменные ягодные купажи, делимся секретами выбора идеального фарфора и учим устраивать красивые чаепития прямо у себя дома. Читайте вдохновляющие статьи, рецепты согревающих напитков и первыми узнавайте о новинках в нашей коллекции посуды.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"swp-sub-note\",\"style\":{\"spacing\":{\"blockGap\":\"10px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-sub-note\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"16px\",\"className\":\"swp-icon-sm\"} -->\n<figure class=\"wp-block-image is-resized swp-icon-sm\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/check-rose.svg\" alt=\"\" style=\"width:16px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"rgba(255,255,255,0.7)\"},\"typography\":{\"fontSize\":\"12.8px\"}}} -->\n<p class=\"has-text-color\" style=\"color:rgba(255,255,255,0.7);font-size:12.8px\">Новые статьи каждую неделю. Никакого спама, только польза и любовь к чаю.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:45%\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Читать блог</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Карусель отзывов\",\"patternName\":\"swp-florist/testimonials\",\"description\":\"Четыре карточки с отзывами, представленные в виде прокручиваемой карусели с рейтингами в виде звёздочек, аватарами клиентов и пагинацией.\",\"categories\":[\"testimonials\",\"swp-florist\"]},\"align\":\"full\",\"className\":\"swp-panel swp-reviews\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|gutter\",\"right\":\"var:preset|spacing|gutter\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"anchor\":\"swp-reviews\"} -->\n<div class=\"wp-block-group alignfull swp-panel swp-reviews\" id=\"swp-reviews\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-right:var(--wp--preset--spacing--gutter);padding-bottom:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--gutter)\"><!-- wp:group {\"className\":\"swp-section-head\",\"style\":{\"spacing\":{\"blockGap\":\"32px\",\"margin\":{\"top\":\"0\",\"bottom\":\"52px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group swp-section-head\" style=\"margin-top:0;margin-bottom:52px\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"640px\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"className\":\"swp-eyebrow\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"16px\"}}}} -->\n<p class=\"swp-eyebrow\" style=\"margin-top:0;margin-bottom:16px\">Добрые слова</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"fontSize\":\"h2\"} -->\n<h2 class=\"wp-block-heading has-h-2-font-size\" style=\"margin-top:0;margin-bottom:0\">Отзывы людей о нашем чае</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\"></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"swp-reviews-slider swiper\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group swp-reviews-slider swiper\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swiper-wrapper\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"},\"anchor\":\"otz\"} -->\n<div id=\"otz\" class=\"wp-block-group swiper-wrapper\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swiper-slide\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swiper-slide\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swp-quote\",\"style\":{\"spacing\":{\"blockGap\":\"18px\",\"padding\":{\"top\":\"32px\",\"right\":\"30px\",\"bottom\":\"32px\",\"left\":\"30px\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swp-quote\" style=\"padding-top:32px;padding-right:30px;padding-bottom:32px;padding-left:30px\"><!-- wp:group {\"className\":\"swp-stars\",\"style\":{\"spacing\":{\"blockGap\":\"4px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group swp-stars\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"swp-quote-text\"} -->\n<p class=\"swp-quote-text\">Заказывала ягодный микс в подарок подруге, но в итоге не удержалась и открыла сама! Аромат потрясающий, ягоды крупные, настоящие, а не пыль из пакетиков. Отдельное спасибо за упаковку — всё приехало в красивой крафтовой коробке, очень эстетично. Буду заказывать ещё!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"swp-quote-who\",\"style\":{\"spacing\":{\"blockGap\":\"14px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-quote-who\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"46px\",\"className\":\"swp-avatar\"} -->\n<figure class=\"wp-block-image is-resized swp-avatar\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/avatars/avatar-1.svg\" alt=\"\" style=\"width:46px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:paragraph {\"className\":\"swp-quote-name\"} -->\n<p class=\"swp-quote-name\">Алина Мерненко</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"swiper-slide\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swiper-slide\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swp-quote\",\"style\":{\"spacing\":{\"blockGap\":\"18px\",\"padding\":{\"top\":\"32px\",\"right\":\"30px\",\"bottom\":\"32px\",\"left\":\"30px\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swp-quote\" style=\"padding-top:32px;padding-right:30px;padding-bottom:32px;padding-left:30px\"><!-- wp:group {\"className\":\"swp-stars\",\"style\":{\"spacing\":{\"blockGap\":\"4px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group swp-stars\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"swp-quote-text\"} -->\n<p class=\"swp-quote-text\">Долго искала стильную чайную пару из тонкого стекла, чтобы эстетично пить чай по утрам. Нашла здесь идеальный вариант. Переживала, доедет ли всё целым, но курьер привёз посылку уже через 1,5 часа, упаковано было намертво в три слоя пупырки. Качество посуды — восторг!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"swp-quote-who\",\"style\":{\"spacing\":{\"blockGap\":\"14px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-quote-who\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"46px\",\"className\":\"swp-avatar\"} -->\n<figure class=\"wp-block-image is-resized swp-avatar\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/avatars/avatar-2.svg\" alt=\"\" style=\"width:46px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:paragraph {\"className\":\"swp-quote-name\"} -->\n<p class=\"swp-quote-name\">Диана Иващенко</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"swiper-slide\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swiper-slide\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swp-quote\",\"style\":{\"spacing\":{\"blockGap\":\"18px\",\"padding\":{\"top\":\"32px\",\"right\":\"30px\",\"bottom\":\"32px\",\"left\":\"30px\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swp-quote\" style=\"padding-top:32px;padding-right:30px;padding-bottom:32px;padding-left:30px\"><!-- wp:group {\"className\":\"swp-stars\",\"style\":{\"spacing\":{\"blockGap\":\"4px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group swp-stars\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"width\":\"15px\"} -->\n<figure class=\"wp-block-image is-resized\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/star.svg\" alt=\"\" style=\"width:15px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"swp-quote-text\"} -->\n<p class=\"swp-quote-text\">Спасли мой вечер! Забыла купить подарок коллеге, вспомнила за пару часов до встречи. Оформила на сайте сет из авторского травяного чая. Привезли день в день точно к назначенному времени. Коллега в восторге. Сервис на высоте, рекомендую!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"swp-quote-who\",\"style\":{\"spacing\":{\"blockGap\":\"14px\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-quote-who\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:image {\"width\":\"46px\",\"className\":\"swp-avatar\"} -->\n<figure class=\"wp-block-image is-resized swp-avatar\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/avatars/avatar-3.svg\" alt=\"\" style=\"width:46px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:paragraph {\"className\":\"swp-quote-name\"} -->\n<p class=\"swp-quote-name\">Дарья Маликова</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"swiper-slide\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swiper-slide\" style=\"padding-top:0;padding-bottom:0\"></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"swp-florist\",\"tagName\":\"footer\"} /-->', 'Главная страница', 'Отображает главную страницу вашего сайта, независимо от того, настроена ли она для отображения последних записей или статической страницы. Шаблон главной страницы имеет приоритет над всеми шаблонами.', 'publish', 'closed', 'closed', '', 'front-page', '', '', '2026-10-09 10:44:58', '2026-10-09 07:44:58', '', 0, 'http://mysitekkr.rus/2026/10/08/front-page/', 0, 'wp_template', '', 0),
(42, 1, '2026-10-08 18:34:44', '2026-10-08 15:34:44', '<!-- wp:group {\"metadata\":{\"name\":\"Заголовок\",\"patternName\":\"swp-florist/header\",\"description\":\"Прикреплённая матовая панель навигации с логотипом, основным меню, элементами управления учётной записью и корзиной, номером телефона студии и кнопкой оформления заказа.\",\"categories\":[\"header\",\"swp-florist\"]},\"className\":\"swp-header\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"},\"position\":{\"type\":\"sticky\",\"top\":\"0px\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group swp-header\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-bottom:0\"><!-- wp:group {\"className\":\"swp-nav is-content-justification-left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"16px\",\"bottom\":\"16px\",\"left\":\"var:preset|spacing|gutter\",\"right\":\"var:preset|spacing|gutter\"},\"blockGap\":\"14px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|plum\"}}},\"position\":{\"type\":\"sticky\",\"top\":\"0px\"}},\"backgroundColor\":\"white\",\"textColor\":\"plum\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"left\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-nav is-content-justification-left has-plum-color has-white-background-color has-text-color has-background has-link-color\" style=\"padding-top:16px;padding-right:var(--wp--preset--spacing--gutter);padding-bottom:16px;padding-left:var(--wp--preset--spacing--gutter)\"><!-- wp:group {\"className\":\"swp-logo\",\"style\":{\"spacing\":{\"blockGap\":\"12px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-logo\"><!-- wp:image {\"id\":26,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"swp-logo-mark\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized swp-logo-mark\" style=\"margin-top:0;margin-bottom:0\"><img src=\"http://mysitekkr.rus/wp-content/uploads/2026/10/1000091603-1.png\" alt=\"\" class=\"wp-image-26\" style=\"width:150px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:navigation {\"ref\":157,\"icon\":\"menu\",\"metadata\":{\"ignoredHookedBlocks\":[\"woocommerce/customer-account\",\"woocommerce/mini-cart\"]},\"style\":{\"spacing\":{\"blockGap\":\"34px\"}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} /-->\n\n<!-- wp:woocommerce/mini-cart {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} /-->\n\n<!-- wp:group {\"className\":\"swp-nav-cta\",\"style\":{\"spacing\":{\"blockGap\":\"14px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-nav-cta\"><!-- wp:group {\"className\":\"swp-nav-phone\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group swp-nav-phone\"><!-- wp:image {\"width\":\"16px\",\"className\":\"swp-icon-sm\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image is-resized swp-icon-sm\" style=\"margin-top:0;margin-bottom:0\"><img src=\"http://mysitekkr.rus/wp-content/themes/swp-florist/assets/images/icons/phone.svg\" alt=\"\" style=\"width:16px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<p style=\"margin-top:0;margin-bottom:0\"><a href=\"tel:+10005555555\">+1 (000) 555-555</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"swp-btn-small\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-buttons swp-btn-small\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://mysitekkr.rus/shop/\">Закажите чай</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'Заголовок', '', 'publish', 'closed', 'closed', '', 'header', '', '', '2026-10-09 10:31:50', '2026-10-09 07:31:50', '', 0, 'http://mysitekkr.rus/2026/10/08/header/', 0, 'wp_template_part', '', 0);
