paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"className\":\"swp-btn-small\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-buttons swp-btn-small\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://mysitekkr.rus/shop/\">Закажите цветы</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'Заголовок', '', 'inherit', 'closed', 'closed', '', '42-revision-v1', '', '', '2026-10-08 19:12:08', '2026-10-08 16:12:08', '', 42, 'http://mysitekkr.rus/?p=53', 0, 'revision', '', 0),
(54, 1, '2026-10-08 19:16:46', '2026-10-08 16:16:46', '{\"styles\":{\"css\":\"header, .wp-block-template-part__header, .is-position-sticky {\\n    position: fixed !important;\\n    top: 0 !important;\\n    z-index: 99999 !important;\\n    width: 100% !important;\\n}\\nbody {\\n    padding-top: 160px !important;\\n}\"},\"settings\":{\"color\":{\"palette\":{\"theme\":[{\"slug\":\"plum\",\"color\":\"#092f19\",\"name\":\"\\u0421\\u043b\\u0438\\u0432\\u043e\\u0432\\u044b\\u0439\"},{\"slug\":\"ink\",\"color\":\"#749173\",\"name\":\"\\u041c\\u044f\\u0433\\u043a\\u0438\\u0435 \\u0447\\u0435\\u0440\\u043d\\u0438\\u043b\\u0430\"},{\"slug\":\"orchid\",\"color\":\"#749173\",\"name\":\"\\u041e\\u0440\\u0445\\u0438\\u0434\\u0435\\u044f\"},{\"slug\":\"orchid-deep\",\"color\":\"#749173\",\"name\":\"\\u0413\\u043b\\u0443\\u0431\\u043e\\u043a\\u0438\\u0439 \\u043e\\u0440\\u0445\\u0438\\u0434\\u0435\\u0435\\u0432\\u044b\\u0439\"},{\"slug\":\"rose\",\"color\":\"#749173\",\"name\":\"\\u0420\\u043e\\u0437\\u0430\"},{\"slug\":\"rose-deep\",\"color\":\"#749173\",\"name\":\"\\u0413\\u043b\\u0443\\u0431\\u043e\\u043a\\u0438\\u0439 \\u0440\\u043e\\u0437\\u043e\\u0432\\u044b\\u0439\"},{\"slug\":\"petal\",\"color\":\"#749173\",\"name\":\"\\u041b\\u0435\\u043f\\u0435\\u0441\\u0442\\u043e\\u043a\"},{\"slug\":\"blush\",\"color\":\"#749173\",\"name\":\"\\u0420\\u0443\\u043c\\u044f\\u043d\\u0435\\u0446\"},{\"slug\":\"lavender\",\"color\":\"#749173\",\"name\":\"\\u041b\\u0430\\u0432\\u0430\\u043d\\u0434\\u043e\\u0432\\u044b\\u0439 \\u0442\\u0443\\u043c\\u0430\\u043d\"},{\"slug\":\"cream\",\"color\":\"#FFFDFC\",\"name\":\"\\u041a\\u0440\\u0435\\u043c\\u043e\\u0432\\u044b\\u0439\"},{\"slug\":\"white\",\"color\":\"#e5e1cf\",\"name\":\"\\u0411\\u0435\\u043b\\u044b\\u0439\"},{\"slug\":\"glass\",\"color\":\"#ffffff\",\"name\":\"\\u0421\\u0442\\u0435\\u043a\\u043b\\u043e\"},{\"slug\":\"sky\",\"color\":\"#ffffff\",\"name\":\"\\u041d\\u0435\\u0431\\u043e\"}]},\"gradients\":{\"theme\":[{\"slug\":\"orchid-gradient\",\"name\":\"\\u041e\\u0440\\u0445\\u0438\\u0434\\u0435\\u044f\",\"gradient\":\"linear-gradient(120deg,rgb(116,145,115) 0%,rgb(116,145,115) 100%)\"},{\"slug\":\"subscription\",\"name\":\"\\u041f\\u0430\\u043d\\u0435\\u043b\\u044c \\u00ab\\u0413\\u043b\\u0443\\u0431\\u043e\\u043a\\u0430\\u044f \\u043e\\u0440\\u0445\\u0438\\u0434\\u0435\\u044f\\u00bb\",\"gradient\":\"linear-gradient(130deg,rgb(151,107,62) 0%,rgb(151,107,62) 100%)\"},{\"slug\":\"petal-soft\",\"name\":\"\\u041d\\u0435\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c \\u043b\\u0435\\u043f\\u0435\\u0441\\u0442\\u043a\\u043e\\u0432\",\"gradient\":\"linear-gradient(160deg,rgb(229,225,207) 0%,rgb(229,225,207) 100%)\"},{\"slug\":\"arch\",\"name\":\"Arch Tint\",\"gradient\":\"linear-gradient(180deg,rgb(229,225,207) 0%,rgb(229,225,207) 100%)\"},{\"slug\":\"stage\",\"name\":\"\\u042d\\u0442\\u0430\\u043f \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\",\"gradient\":\"linear-gradient(160deg,rgb(229,225,207) 0%,rgb(229,225,207) 55%,rgb(229,225,207) 100%)\"}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '18-revision-v1', '', '', '2026-10-08 19:16:46', '2026-10-08 16:16:46', '', 18, 'http://mysitekkr.rus/?p=54', 0, 'revision', '', 0),
